insert into public.ls_items (code, grp, title, descr, sort) values
('LS-01', 'أعمال عامة وتحضيرية', 'تطوير كامل للنطاق', 'تطوير كامل للنطاق المحدد في المخططات يشمل: أعمال الإزالة والتفكيك، الحوائط والقواطع، الأرضيات والوزرات، الأسقف، الدهانات والتكسيات، الأبواب والواجهات، التمديدات الكهربائية والإنارة، التيار الخفيف وإنذار الحريق، التكييف والتهوية، الأعمال الصحية، التنظيف والتشغيل والتسليم؛ وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للاستخدام حسب المخططات والمواصفات.', 10),
('LS-02', 'أعمال عامة وتحضيرية', 'أعمال الإزالة والتفكيك', 'إزالة وتفكيك الحوائط والقواطع والأرضيات والوزرات والأسقف المستعارة والجبسية والأبواب والتمديدات الكهربائية والميكانيكية والصحية القائمة في نطاق العمل حسب المخططات، مع فصل الخدمات بأمان، وفرز المخلفات ونقلها إلى المواقع المعتمدة، وتسليم ما تطلبه الإدارة من المواد المفكّكة.', 20),
('LS-03', 'أعمال عامة وتحضيرية', 'الحماية والحواجز المؤقتة وتنظيم الموقع', 'توريد وتركيب حواجز الغبار والعزل المؤقت ومسارات الحركة البديلة واللوحات التحذيرية، وحماية الأرضيات والأجهزة والمناطق التشغيلية المجاورة، والالتزام بمتطلبات مكافحة العدوى (ICRA) والسلامة والعمل خارج أوقات الذروة عند الطلب، وإزالة كل ذلك عند الانتهاء.', 30),
('LS-04', 'أعمال عامة وتحضيرية', 'أعمال الهدم الإنشائي والفتحات والتدعيم', 'عمل الفتحات في الحوائط والأسقف وإزالة العناصر الإنشائية غير الحاملة، وتدعيم وتقوية ما يلزم بالكمرات والأعتاب والزوايا الحديدية حسب المخططات وتقرير المهندس الإنشائي، شاملاً الحماية والتثبيت المؤقت.', 40),
('LS-05', 'الأعمال المعمارية والتشطيبات', 'الحوائط والقواطع الجديدة', 'توريد وتنفيذ الحوائط والقواطع الجديدة (بلوك / جبس بورد مزدوج مع عزل صوتي / قواطع زجاجية حسب المخططات) شاملة الهياكل الحاملة والأعتاب وتسليك الخدمات داخلها والمعجون والتجهيز للدهان.', 50),
('LS-06', 'الأعمال المعمارية والتشطيبات', 'أعمال الأرضيات والوزرات', 'توريد وتركيب الأرضيات الجديدة (بورسلين / جرانيت / فينيل طبي / إيبوكسي حسب المخططات) شاملة إزالة القديم وتسوية الفرشة والميول والعزل حيث يلزم، والوزرات والفواصل والبروفيلات المعدنية، وفق مواصفات المنشآت الصحية.', 60),
('LS-07', 'الأعمال المعمارية والتشطيبات', 'أعمال الأسقف', 'توريد وتركيب الأسقف المستعارة (بلاطات معدنية / جبسية / مقاومة للرطوبة) والأسقف الجبسية والتفاصيل المعمارية وفتحات الصيانة حسب المخططات، شاملة الهيكل الحامل والتعليق وفتحات الإنارة والتكييف وجميع الملحقات.', 70),
('LS-08', 'الأعمال المعمارية والتشطيبات', 'أعمال الدهانات', 'تجهيز الأسطح (كشط، معجون، صنفرة، أساس) ودهان الحوائط والأسقف بدهانات صحية قابلة للغسيل ومضادة للبكتيريا حسب المواصفات وبالألوان المعتمدة، شاملاً دهان الأبواب والعناصر المعدنية والخشبية حيث يلزم.', 80),
('LS-09', 'الأعمال المعمارية والتشطيبات', 'تكسية الحوائط والواقيات', 'توريد وتركيب تكسيات الحوائط (HPL / ألواح واقية / سيراميك حسب المخططات) وواقيات الأركان ومساكات الممرات ودرابزين الحماية، شاملة الهياكل والمواد اللاصقة والتشطيب.', 90),
('LS-10', 'الأعمال المعمارية والتشطيبات', 'الأبواب والشبابيك والإكسسوارات', 'توريد وتركيب الأبواب (خشبية / معدنية / مقاومة للحريق حسب المخططات) بإطاراتها وأقفالها ومفصلاتها وغالقاتها وواقياتها ولوحاتها، والشبابيك وملحقاتها، مع ضبط التشغيل والتسليم.', 100),
('LS-11', 'الأعمال المعمارية والتشطيبات', 'الواجهات الزجاجية والأبواب الأوتوماتيكية', 'توريد وتركيب الواجهات الزجاجية والأبواب الأوتوماتيكية المنزلقة (زجاج مقسّى / مزدوج حسب المخططات) بأنظمة الألمنيوم والحساسات والمحركات وبطاريات الطوارئ والأقفال، مع البرمجة والاختبار والضمان.', 110),
('LS-12', 'الأعمال المعمارية والتشطيبات', 'الواجهات الخارجية والكلادينج', 'توريد وتركيب تكسية الواجهات الخارجية (ألمنيوم مركب / حجر / GRC حسب المخططات) بهياكلها المعدنية وعزلها وتفاصيل الوصلات والمزاريب، شاملة السقالات وإزالة التكسية القديمة.', 120),
('LS-13', 'الأعمال المعمارية والتشطيبات', 'أعمال العزل المائي والحراري', 'توريد وتنفيذ أعمال العزل المائي للأسطح ودورات المياه والمناطق الرطبة، والعزل الحراري حسب المواصفات، شاملة تجهيز الأسطح والطبقات الحامية والاختبار بالماء.', 130),
('LS-14', 'الأعمال المعمارية والتشطيبات', 'تأهيل دورات المياه', 'تأهيل كامل لدورات المياه في النطاق: إزالة القديم، العزل، الأرضيات والجدران، الأطقم الصحية والخلاطات والإكسسوارات وقواطع المراحيض والمرايا والتهوية والإنارة، شاملاً تمديدات التغذية والصرف حسب المخططات ومتطلبات ذوي الإعاقة.', 140),
('LS-15', 'الأعمال المعمارية والتشطيبات', 'النجارة والتأثيث الثابت', 'توريد وتركيب الكاونترات والخزائن والأرفف والتأثيث الثابت (كاونتر الاستقبال، وحدات التخزين) بالمواد والتشطيبات المعتمدة حسب المخططات، شاملة الأسطح والإكسسوارات والتثبيت.', 150),
('LS-16', 'الأعمال المعمارية والتشطيبات', 'اللوحات الإرشادية واللافتات', 'توريد وتركيب اللوحات الإرشادية الداخلية والخارجية ولوحات الأقسام والغرف ولافتات السلامة ولوحات المدخل المضيئة حسب دليل الهوية والمخططات.', 160),
('LS-17', 'الأعمال الكهربائية والتيار الخفيف', 'التمديدات الكهربائية', 'إزالة واستبدال كامل للتمديدات الكهربائية في النطاق: المواسير والمجاري والأسلاك والكيابل والأفياش والمفاتيح والمخارج ونقاط التغذية للأجهزة، والتأريض، حسب المخططات ومواصفات الكود السعودي، شاملاً الاختبار والتوصيل باللوحات.', 170),
('LS-18', 'الأعمال الكهربائية والتيار الخفيف', 'أعمال الإنارة', 'توريد وتركيب وحدات الإنارة الجديدة (LED) الداخلية بأنواعها ووحدات إنارة الطوارئ ولوحات المخارج، مع التحكم والحساسات حيث يلزم، وإزالة الوحدات القديمة، حسب المخططات ومستويات الإضاءة المطلوبة.', 180),
('LS-19', 'الأعمال الكهربائية والتيار الخفيف', 'لوحات التوزيع والتغذية الرئيسية', 'توريد وتركيب لوحات التوزيع الفرعية والقواطع والكيابل الرئيسية من المصدر إلى اللوحات، وتعديل اللوحات القائمة، مع الترقيم والاختبار والتسليم حسب المخططات.', 190),
('LS-20', 'الأعمال الكهربائية والتيار الخفيف', 'أنظمة التيار الخفيف', 'توريد وتمديد وتركيب أنظمة التيار الخفيف: شبكة البيانات والهاتف، نداء الممرضات، كاميرات المراقبة، نظام الصوت والإذاعة، التحكم بالدخول، شاملة المخارج والكيابل واللوحات والاختبار والتسليم حسب المخططات.', 200),
('LS-21', 'الأعمال الكهربائية والتيار الخفيف', 'نظام إنذار الحريق', 'تعديل وتوسعة نظام إنذار الحريق في النطاق: الكواشف والجرس والأضواء ونقاط الإنذار اليدوية والكيابل والربط باللوحة الرئيسية، مع البرمجة والاختبار والتسليم للجهات المختصة.', 210),
('LS-22', 'الأعمال الميكانيكية', 'أعمال التكييف والتهوية', 'إزالة واستبدال / إعادة توزيع أعمال التكييف والتهوية في النطاق: الوحدات ومجاري الهواء والعزل ومخارج ومراجع الهواء والدمبرات والتحكم، والتوصيل بالنظام القائم، شاملة الاختبار والموازنة والتشغيل حسب المخططات.', 220),
('LS-23', 'الأعمال الميكانيكية', 'الأعمال الصحية والصرف', 'إزالة واستبدال تمديدات التغذية بالمياه (حار / بارد) والصرف والتهوية، والأطقم الصحية والخلاطات والصمامات والملحقات، حسب المخططات، شاملة الاختبار بالضغط والتوصيل بالشبكات القائمة.', 230),
('LS-24', 'الأعمال الميكانيكية', 'نظام الإطفاء', 'تعديل وتوسعة نظام الإطفاء بالمياه في النطاق (رشاشات، خزائن خراطيم، طفايات) حسب المخططات ومتطلبات الدفاع المدني، شاملاً الدعامات والاختبار والتسليم.', 240),
('LS-25', 'الأعمال الميكانيكية', 'الغازات الطبية', 'تمديد وتركيب مخارج الغازات الطبية (أكسجين، هواء طبي، شفط) ومواسيرها النحاسية وصمامات العزل ولوحات الإنذار في النطاق حسب المخططات والمواصفات، مع الاختبار والاعتماد.', 250),
('LS-26', 'الأعمال الميكانيكية', 'سخانات ومضخات وخزانات المياه', 'توريد وتركيب / استبدال سخانات المياه والمضخات وخزانات المياه وملحقاتها ولوحات التحكم حسب المخططات، شاملة التوصيلات والعزل والاختبار والتشغيل.', 260),
('LS-27', 'الأعمال الخارجية والموقع', 'أعمال الموقع العام والأرصفة', 'تأهيل الأرصفة والممرات والمداخل الخارجية (إنترلوك / خرسانة / جرانيت حسب المخططات) شاملة الحفر والتسوية والطبقات التحتية والبردورات والتصريف السطحي.', 270),
('LS-28', 'الأعمال الخارجية والموقع', 'المظلات والمنحدرات وممرات ذوي الإعاقة', 'توريد وتنفيذ مظلات المداخل والمنحدرات والدرابزين والمسارات المخصصة لذوي الإعاقة حسب المخططات وكود البناء السعودي لمتطلبات الوصول الشامل.', 280),
('LS-29', 'الأعمال الخارجية والموقع', 'التشجير والري', 'تنفيذ أعمال التشجير والمسطحات الخضراء وشبكة الري الآلي والتحكم في نطاق العمل حسب المخططات، شاملة التربة الزراعية والصيانة خلال فترة الضمان.', 290),
('LS-30', 'الأعمال الخارجية والموقع', 'الإنارة الخارجية', 'توريد وتركيب أعمدة ووحدات الإنارة الخارجية (LED) وإنارة الواجهات والمداخل والتمديدات والتحكم الزمني حسب المخططات، مع إزالة القديم والاختبار.', 300),
('LS-31', 'التشغيل والتسليم', 'الاختبار والتشغيل والموازنة', 'إجراء اختبارات التشغيل والموازنة لجميع الأنظمة (كهرباء، تكييف، صحية، إطفاء، تيار خفيف) بحضور ممثل الإدارة، ومعالجة الملاحظات، وتقديم تقارير الاختبار المعتمدة.', 310),
('LS-32', 'التشغيل والتسليم', 'التنظيف النهائي والتسليم والوثائق', 'التنظيف النهائي الشامل وإزالة المخلفات وإصلاح ما تضرر من المناطق المجاورة، وتسليم المخططات كما نُفِّذ (As-built) وشهادات الضمان والكتيبات وقطع الغيار الاحتياطية، وتدريب فريق التشغيل.', 320),
('LS-33', 'التشغيل والتسليم', 'السلامة والتصاريح والتنسيق', 'الالتزام بمتطلبات السلامة والصحة المهنية ومكافحة العدوى، واستخراج التصاريح اللازمة، والتنسيق مع الأقسام التشغيلية والجهات المختصة طوال مدة التنفيذ، وتقديم خطة العمل والجدول الزمني والتقارير الدورية.', 330)
insert into public.ls_templates (name, codes, sort) select * from (values
('تطوير مدخل رئيسي', array['LS-02','LS-03','LS-04','LS-05','LS-06','LS-07','LS-08','LS-09','LS-10','LS-11','LS-15','LS-16','LS-17','LS-18','LS-20','LS-21','LS-22','LS-24','LS-31','LS-32','LS-33']::text[], 10),
('تأهيل عام (قسم / جناح)', array['LS-02','LS-03','LS-05','LS-06','LS-07','LS-08','LS-09','LS-10','LS-17','LS-18','LS-21','LS-22','LS-23','LS-31','LS-32','LS-33']::text[], 20),
('تأهيل دورات مياه', array['LS-02','LS-03','LS-13','LS-14','LS-17','LS-18','LS-22','LS-23','LS-32']::text[], 30),
('تأهيل الواجهات والموقع الخارجي', array['LS-03','LS-12','LS-13','LS-27','LS-28','LS-29','LS-30','LS-32']::text[], 40)) as v(name, codes, sort) where not exists (select 1 from public.ls_templates);
