-- ===== قائمة بنود المقطوعية وقوالب النطاقات في قاعدة البيانات (تُدار من صفحة الإدارة) =====
create table if not exists public.ls_items (code text primary key, grp text not null, title text not null, descr text not null default '', sort int not null default 0, active boolean not null default true, updated_at timestamptz not null default now());
create table if not exists public.ls_templates (id serial primary key, name text not null, codes text[] not null default '{}', sort int not null default 0, active boolean not null default true, updated_at timestamptz not null default now());
alter table public.ls_items enable row level security; alter table public.ls_templates enable row level security;
drop policy if exists p_read on public.ls_items; create policy p_read on public.ls_items for select using (public.can_read());
drop policy if exists p_adm on public.ls_items; create policy p_adm on public.ls_items for all using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.ls_items to authenticated;
drop policy if exists p_read on public.ls_templates; create policy p_read on public.ls_templates for select using (public.can_read());
drop policy if exists p_adm on public.ls_templates; create policy p_adm on public.ls_templates for all using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.ls_templates to authenticated;
grant usage, select on sequence public.ls_templates_id_seq to authenticated;
on conflict (code) do nothing;
